"""Word Break — DP over reachable prefix boundaries.

`reachable[i]` means s[:i] can be segmented; extend it by any dictionary word.

Time: O(n^2 * L)   Space: O(n)
"""
from typing import List


class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        words = set(wordDict)
        reachable = [True] + [False] * len(s)
        for end in range(1, len(s) + 1):
            for start in range(end):
                if reachable[start] and s[start:end] in words:
                    reachable[end] = True
                    break
        return reachable[-1]
